<?php
if(wp_get_environment_type()!=='local'||home_url()!=='http://127.0.0.1:8877')WP_CLI::error('Isolated local installation required.');
$dir=dirname(ABSPATH,3).'/runtime/cx';$file=$dir.'/commerce-private.json';$mode=getenv('PPT_CX_COMMERCE_MODE')?:'prepare';$store=WC_Data_Store::load('customer-download');
if($mode!=='prepare'){
 $f=json_decode(file_get_contents($file),true);$permission=$mode==='cleanup'?null:new WC_Customer_Download($f['permission']);
 if($mode==='expired'){$permission->set_access_expires(time()-DAY_IN_SECONDS);$permission->save();}
 if($mode==='exhausted'){$permission->set_access_expires(null);$permission->set_downloads_remaining(0);$permission->save();}
 if($mode==='revoked')$permission->delete(true);
 if($mode==='cleanup'){foreach($f['orders']as $id){$o=wc_get_order($id);if($o)$o->delete(true);}foreach($f['products']as $id){$p=wc_get_product($id);if($p)$p->delete(true);}unlink($file);}
 WP_CLI::success($mode);return;
}
if(file_exists($file))WP_CLI::error('Clean up earlier fixtures first.');
$checks=array();$check=function($name,$pass,$detail=null)use(&$checks){$checks[]=array('test'=>$name,'pass'=>(bool)$pass,'detail'=>$detail);};
$products=array();$orders=array();$download_source=wc_get_product(wc_get_product_id_by_sku('PPT-DEMO-4'));$downloads=$download_source->get_downloads();$download=reset($downloads);
foreach(array('print'=>array('12.50',false),'digital'=>array('6.00',true))as $name=>$settings){$p=new WC_Product_Simple();$p->set_name('Local CX '.$name.' verification');$p->set_status('publish');$p->set_regular_price($settings[0]);$p->set_virtual($settings[1]);if($settings[1]){$p->set_downloadable(true);$p->set_downloads(array($download));$p->set_download_limit(4);}$p->save();$products[$name]=$p->get_id();}
WC()->session=new WC_Session_Handler();WC()->customer=new WC_Customer(0);WC()->customer->set_billing_country('GB');WC()->customer->set_shipping_country('GB');WC()->customer->set_shipping_postcode('SW1A 1AA');WC()->customer->set_calculated_shipping(true);WC()->cart=new WC_Cart();
foreach(array('print'=>array('print'),'digital'=>array('digital'),'mixed'=>array('print','digital'))as $kind=>$items){WC()->cart->empty_cart();foreach($items as $item)WC()->cart->add_to_cart($products[$item]);WC()->cart->calculate_totals();$shipping=WC()->cart->needs_shipping();$expected=$kind!=='digital';$check($kind.' cart uses the correct shipping requirement',$shipping===$expected,array('shipping_required'=>$shipping,'subtotal'=>WC()->cart->get_subtotal(),'shipping'=>WC()->cart->get_shipping_total(),'total'=>WC()->cart->get_total('edit')));if(!$expected)$check('Digital-only cart has no shipping charge',(float)WC()->cart->get_shipping_total()===0.0);else $check($kind.' cart has a native delivery rate',(float)WC()->cart->get_shipping_total()>0);}
WC()->cart->empty_cart();$email='cx-commerce-'.time().'@example.test';$o=wc_create_order();$orders[]=$o->get_id();$o->set_billing_email($email);$o->add_product(wc_get_product($products['digital']),1);$o->calculate_totals();$o->save();$check('Unpaid paid-edition order has no entitlement',!$o->is_download_permitted()&&!$store->get_downloads(array('order_id'=>$o->get_id())));
$o->update_status('completed','Local test: simulated settlement, no gateway or money.');$permissions=$store->get_downloads(array('order_id'=>$o->get_id()));$permission=reset($permissions);$urls=$o->get_downloadable_items();$entry=reset($urls);$check('Simulated settled order receives native download entitlement',$o->is_download_permitted()&&count($permissions)===1&&$permission&&$entry);
$retry=wc_create_order();$orders[]=$retry->get_id();$retry->set_billing_email($email);$retry->add_product(wc_get_product($products['print']),1);$retry->calculate_totals();$retry->update_status('failed','Local failed-payment fixture; no gateway called.');$retry->save();$check('Failed order exposes a native payment retry URL',$retry->needs_payment()&&strpos($retry->get_checkout_payment_url(),'/order-pay/')!==false);$before=count(wc_get_orders(array('billing_email'=>$email,'limit'=>-1)));$gateway=new WC_Gateway_BACS();$response=$gateway->process_payment($retry->get_id());$after=count(wc_get_orders(array('billing_email'=>$email,'limit'=>-1)));$check('Native offline retry reuses the order without a duplicate',($response['result']??'')==='success'&&$before===$after&&wc_get_order($retry->get_id())->get_status()==='on-hold');
file_put_contents($file,wp_json_encode(array('products'=>$products,'orders'=>$orders,'permission'=>$permission->get_id(),'url'=>$entry['download_url'],'direct'=>$download->get_file())));file_put_contents($dir.'/commerce-core.json',wp_json_encode($checks,JSON_PRETTY_PRINT));echo wp_json_encode(array('checks'=>count($checks),'failures'=>array_values(array_filter($checks,function($c){return !$c['pass'];}))));
